/* Standalone Canvas 2D motion graphic. All artwork is procedural and human-free. */
(function(root){
  'use strict';
  const META={"id": "01_self_service_airport_check_in_kiosk_activation", "title": "Self-Service Airport Check-In Kiosk Activation", "width": 3840, "height": 2160, "fps": 60, "duration": 20, "scenes": 1, "background": "#F5F0E7", "targetVideoBitrate": 100000000, "humanFigures": false};
  const W=1920,H=1080,PI=Math.PI,TAU=PI*2;
  const C={ink:'#263A4F',paper:'#FFFFFF',blue:'#70AACA',pale:'#E0EDF3',green:'#63B397',mint:'#E3F1E9',
    gold:'#E5BB68',sand:'#F7EDD8',red:'#D77974',gray:'#9AAEBA',muted:'#728999',navy:'#2B435D'};
  const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
  const mix=(a,b,p)=>a+(b-a)*clamp(p);
  const ease=p=>{p=clamp(p);return p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;};
  const ramp=(t,a,b)=>ease((t-a)/(b-a));
  function color(a,b,p){
    const rgb=x=>[1,3,5].map(i=>parseInt(x.slice(i,i+2),16));const aa=rgb(a),bb=rgb(b);
    return '#'+aa.map((v,i)=>Math.round(mix(v,bb[i],p)).toString(16).padStart(2,'0')).join('');
  }
  function paint(ctx,fill,stroke=C.ink,lw=9){
    if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke&&lw>0){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function rr(ctx,x,y,w,h,r=18,fill=C.paper,stroke=C.ink,lw=9){
    r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
    ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();paint(ctx,fill,stroke,lw);
  }
  function circle(ctx,x,y,r,fill=C.paper,stroke=C.ink,lw=8){ctx.beginPath();ctx.arc(x,y,r,0,TAU);paint(ctx,fill,stroke,lw);}
  function poly(ctx,pts,fill,stroke=C.ink,lw=8,close=true){
    ctx.beginPath();ctx.moveTo(...pts[0]);for(let i=1;i<pts.length;i++)ctx.lineTo(...pts[i]);if(close)ctx.closePath();paint(ctx,fill,stroke,lw);
  }
  function line(ctx,x1,y1,x2,y2,stroke=C.ink,lw=8){poly(ctx,[[x1,y1],[x2,y2]],null,stroke,lw,false);}
  function drawPath(ctx,pts,p,stroke=C.ink,lw=8){
    const lengths=pts.slice(1).map((pt,i)=>Math.hypot(pt[0]-pts[i][0],pt[1]-pts[i][1]));
    let left=lengths.reduce((a,b)=>a+b,0)*clamp(p);ctx.beginPath();ctx.moveTo(...pts[0]);
    for(let i=0;i<lengths.length&&left>0;i++){const q=Math.min(1,left/lengths[i]);ctx.lineTo(mix(pts[i][0],pts[i+1][0],q),mix(pts[i][1],pts[i+1][1],q));left-=lengths[i];}
    ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();
  }
  function pointOn(pts,p){
    const lengths=pts.slice(1).map((pt,i)=>Math.hypot(pt[0]-pts[i][0],pt[1]-pts[i][1]));
    let left=lengths.reduce((a,b)=>a+b,0)*clamp(p);
    for(let i=0;i<lengths.length;i++){if(left<=lengths[i]||i===lengths.length-1){const q=clamp(left/lengths[i]);return [mix(pts[i][0],pts[i+1][0],q),mix(pts[i][1],pts[i+1][1],q)];}left-=lengths[i];}
    return pts[pts.length-1];
  }
  function label(ctx,text,x,y,size=30,opts={}){
    ctx.save();ctx.textAlign=opts.align||'center';ctx.textBaseline='middle';
    const family='Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';let s=size;
    ctx.font=(opts.weight||600)+' '+s+'px '+family;
    if(opts.maxWidth&&ctx.measureText(text).width>opts.maxWidth){s*=opts.maxWidth/ctx.measureText(text).width;ctx.font=(opts.weight||600)+' '+s+'px '+family;}
    if(ctx.__auditTextFit)ctx.__auditTextFit.push({text,width:ctx.measureText(text).width,maxWidth:opts.maxWidth||null,size:s});
    ctx.fillStyle=opts.color||C.ink;ctx.fillText(text,x,y);ctx.restore();
  }
  function group(ctx,t,start,cx,cy,fn,duration=.9){
    const p=ramp(t,start,start+duration);if(p<=0)return;ctx.save();ctx.globalAlpha*=p;
    ctx.translate(cx,cy+14*(1-p));const s=mix(.975,1,p);ctx.scale(s,s);ctx.translate(-cx,-cy);fn();ctx.restore();
  }
  function check(ctx,x,y,s,p=1,stroke=C.ink,lw=9){drawPath(ctx,[[x-s*.37,y],[x-s*.09,y+s*.26],[x+s*.42,y-s*.28]],p,stroke,lw);}
  function led(ctx,x,y,fill,r=10){circle(ctx,x,y,r,fill,C.ink,4);}
  function chip(ctx,x,y,s,fill=C.gold){
    rr(ctx,x-s*.33,y-s*.31,s*.66,s*.62,s*.09,fill,C.ink,s*.06);
    rr(ctx,x-s*.12,y-s*.13,s*.24,s*.26,s*.025,null,C.ink,s*.035);
    for(const side of [-1,1])for(let i=0;i<3;i++){
      line(ctx,x+side*s*.33,y+s*(i-1)*.19,x+side*s*.48,y+s*(i-1)*.19,C.ink,s*.045);
      line(ctx,x+s*(i-1)*.19,y+side*s*.31,x+s*(i-1)*.19,y+side*s*.45,C.ink,s*.045);
    }
  }
  function plane(ctx,x,y,s,fill=C.blue,angle=0){
    ctx.save();ctx.translate(x,y);ctx.rotate(angle);
    poly(ctx,[[s*.61,0],[s*.10,-s*.10],[-s*.16,-s*.45],[-s*.30,-s*.45],[-s*.22,-s*.10],
      [-s*.48,-s*.07],[-s*.58,-s*.24],[-s*.68,-s*.24],[-s*.61,0],[-s*.68,s*.24],
      [-s*.58,s*.24],[-s*.48,s*.07],[-s*.22,s*.10],[-s*.30,s*.45],[-s*.16,s*.45],[s*.10,s*.10]],fill,C.ink,s*.045);
    ctx.restore();
  }
  function passport(ctx,x,y,w,h,open=false){
    if(!open){
      rr(ctx,x,y,w,h,13,C.blue,C.ink,7);label(ctx,'PASSPORT',x+w/2,y+h*.20,Math.min(23,w*.15),{maxWidth:w-28});
      circle(ctx,x+w/2,y+h*.49,w*.20,C.pale,C.ink,5);
      ctx.save();ctx.beginPath();ctx.arc(x+w/2,y+h*.49,w*.20,0,TAU);ctx.clip();
      line(ctx,x+w*.30,y+h*.49,x+w*.70,y+h*.49,C.ink,4);
      ctx.beginPath();ctx.ellipse(x+w/2,y+h*.49,w*.10,w*.20,0,0,TAU);paint(ctx,null,C.ink,4);ctx.restore();
      chip(ctx,x+w/2,y+h*.79,w*.15,C.gold);
    }else{
      rr(ctx,x,y,w,h,10,C.paper,C.ink,7);line(ctx,x+w*.5,y+7,x+w*.5,y+h-7,C.ink,5);
      chip(ctx,x+w*.25,y+h*.43,w*.20,C.gold);
      for(let i=0;i<4;i++)line(ctx,x+w*.57,y+h*.22+i*h*.12,x+w*.91,y+h*.22+i*h*.12,C.gray,4);
      for(let i=0;i<2;i++)line(ctx,x+w*.09,y+h*.76+i*h*.10,x+w*.90,y+h*.76+i*h*.10,C.ink,3);
    }
  }
  function suitcase(ctx,x,y,w,h,fill=C.gold){
    const stroke=Math.max(3,w*.034),wr=Math.max(2.6,w*.044);
    rr(ctx,x+w*.34,y-h*.10,w*.32,h*.13,Math.max(3,w*.034),C.paper,C.ink,Math.max(2.5,w*.030));
    rr(ctx,x,y,w,h,Math.max(4,w*.077),fill,C.ink,stroke);
    for(const p of [.23,.5,.77])line(ctx,x+w*p,y+h*.09,x+w*p,y+h*.91,C.ink,Math.max(2,w*.021));
    circle(ctx,x+w*.18,y+h+wr*.95,wr,C.ink,null,0);circle(ctx,x+w*.82,y+h+wr*.95,wr,C.ink,null,0);
  }
  function seat(ctx,x,y,s,fill=C.blue){
    rr(ctx,x-s*.32,y-s*.43,s*.64,s*.50,s*.09,fill,C.ink,s*.065);
    rr(ctx,x-s*.38,y+s*.08,s*.76,s*.25,s*.07,fill,C.ink,s*.065);
    for(const p of [-.28,.28])line(ctx,x+s*p,y+s*.33,x+s*p,y+s*.48,C.ink,s*.07);
  }
  function barcode(ctx,x,y,w,h,seed=0){
    let cursor=0,index=0;ctx.fillStyle=C.ink;
    while(cursor<w){const v=1+((index*7+seed*3)%3),space=1+((index*5+seed)%2);const step=w/70;
      const bw=Math.min(w-cursor,v*step);ctx.fillRect(x+cursor,y,bw,h);cursor+=bw+space*step;index++;}
  }
  function ticket(ctx,x,y,w,h){
    rr(ctx,x,y,w,h,10,C.paper,C.ink,6);
    label(ctx,'BOARDING PASS',x+w*.43,y+26,21,{maxWidth:w*.69});plane(ctx,x+w*.87,y+27,31,C.blue);
    line(ctx,x+15,y+48,x+w-15,y+48,C.gray,3);
    label(ctx,'AAA',x+w*.20,y+77,25,{maxWidth:w*.24});label(ctx,'BBB',x+w*.75,y+77,25,{maxWidth:w*.24});
    line(ctx,x+w*.38,y+77,x+w*.55,y+77,C.ink,4);poly(ctx,[[x+w*.55-8,y+71],[x+w*.55,y+77],[x+w*.55-8,y+83]],null,C.ink,3,false);
    label(ctx,'SEAT 12C',x+w*.25,y+112,18,{maxWidth:w*.4});label(ctx,'GATE C12',x+w*.75,y+112,18,{maxWidth:w*.4});
    barcode(ctx,x+20,y+h-48,w-40,27,4);
  }
  function tag(ctx,x,y,w,h){
    rr(ctx,x,y,w,h,8,C.paper,C.ink,6);circle(ctx,x+w/2,y+17,4,C.paper,C.ink,3);
    label(ctx,'BAG TAG',x+w/2,y+45,19,{maxWidth:w-20});
    label(ctx,'AAA',x+w/2,y+76,22,{maxWidth:w-20});barcode(ctx,x+16,y+100,w-32,54,1);
    label(ctx,'BBB',x+w/2,y+183,22,{maxWidth:w-20});barcode(ctx,x+16,y+205,w-32,41,5);
  }
  function shield(ctx,x,y,s,p=1,tick=0,fill=C.mint,stroke=C.ink){
    const pts=[[x,y-s*.64],[x+s*.52,y-s*.38],[x+s*.44,y+s*.20],[x+s*.25,y+s*.49],[x,y+s*.70],
      [x-s*.25,y+s*.49],[x-s*.44,y+s*.20],[x-s*.52,y-s*.38],[x,y-s*.64]];
    if(p>=.999)poly(ctx,pts,fill,stroke,9);else drawPath(ctx,pts,p,stroke,9);
    if(tick>0)check(ctx,x,y,s*.74,tick,stroke,11);
  }
  function progress(ctx,x,y,w,h,p,fill=C.blue){rr(ctx,x,y,w,h,h/2,C.pale,C.ink,5);
    ctx.save();rr(ctx,x+3,y+3,w-6,h-6,(h-6)/2,null,null,0);ctx.clip();
    ctx.fillStyle=fill;ctx.fillRect(x+3,y+3,(w-6)*clamp(p),h-6);ctx.restore();
  }
  function kiosk(ctx,x,y,w,h,screenFn,opts={}){
    const head=h*.62;
    poly(ctx,[[x+w*.34,y+head+h*.16],[x+w*.66,y+head+h*.16],[x+w*.72,y+h-19],[x+w*.28,y+h-19]],C.pale,C.ink,9);
    rr(ctx,x+w*.10,y+h-22,w*.80,24,12,C.paper,C.ink,8);
    rr(ctx,x,y+head+13,w,h*.16,14,C.pale,C.ink,9);
    rr(ctx,x+w*.12,y+head+41,w*.29,32,7,C.navy,C.ink,5);
    line(ctx,x+w*.14,y+head+56,x+w*.39,y+head+56,C.gray,4);
    rr(ctx,x+w*.55,y+head+43,w*.32,13,6,C.ink,null,0);
    led(ctx,x+w*.88,y+head+90,opts.led||C.green,7);
    rr(ctx,x,y,w,head,26,C.paper,C.ink,10);
    const s={x:x+26,y:y+26,w:w-52,h:head-52};
    rr(ctx,s.x,s.y,s.w,s.h,14,opts.screen||'#F2F6F7',C.ink,6);
    ctx.save();rr(ctx,s.x+3,s.y+3,s.w-6,s.h-6,11,null,null,0);ctx.clip();screenFn(s);ctx.restore();
  }
  function status(ctx,text,fill=C.green,y=943,dark=false){
    rr(ctx,580,y-38,760,76,21,dark?'#2F455E':C.paper,dark?'#9DB6C7':C.ink,7);
    led(ctx,619,y,fill,10);label(ctx,text,974,y,30,{maxWidth:644,color:dark?'#F0F6FA':C.ink});
  }
  function region(ctx,name,x,y,w,h){if(ctx.__auditRegions)ctx.__auditRegions.push({name,x,y,w,h});}
  function scene(ctx,t){

    const boot=ramp(t,2.3,5.9);
    group(ctx,t,.4,960,503,()=>kiosk(ctx,690,140,540,730,s=>{
      label(ctx,'AIRPORT CHECK-IN',960,222,34,{maxWidth:440});
      group(ctx,t,1.5,960,307,()=>plane(ctx,960,307,110,C.blue));
      group(ctx,t,2,960,382,()=>{
        progress(ctx,774,365,372,21,boot,C.blue);
        label(ctx,boot>.99?'READY':'INITIALIZING',960,407,22,{maxWidth:370});
      });
      ['DOCUMENT','SEAT','BAGGAGE'].forEach((name,i)=>{
        const x=749+i*144;
        group(ctx,t,6.0+i*.35,x+61,483,()=>{
          rr(ctx,x,435,122,99,13,C.paper,C.ink,5);
          if(i===0)chip(ctx,x+61,469,38,C.gold);
          if(i===1)seat(ctx,x+61,470,43,C.blue);
          if(i===2)suitcase(ctx,x+44,451,34,40,C.gold);
          label(ctx,name,x+61,515,18,{maxWidth:103});
        });
      });
    },{led:boot>.99?C.green:C.gold}));
    group(ctx,t,1.5,960,943,()=>status(ctx,t>7.7?'Kiosk ready for check-in':'Starting the check-in kiosk',t>7.7?C.green:C.gold));
    region(ctx,'kiosk',680,130,560,756);

  }
  function render(ctx,seconds,width=ctx.canvas.width,height=ctx.canvas.height){
    if(!Number.isFinite(seconds))throw new TypeError('seconds must be finite');
    const t=clamp(seconds,0,META.duration);ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;
    ctx.globalCompositeOperation='source-over';ctx.fillStyle=META.background;ctx.fillRect(0,0,width,height);
    const scale=Math.min(width/W,height/H);ctx.translate((width-W*scale)/2,(height-H*scale)/2);ctx.scale(scale,scale);
    ctx.beginPath();ctx.rect(0,0,W,H);ctx.clip();ctx.lineCap='round';ctx.lineJoin='round';ctx.setLineDash([]);
    ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;ctx.shadowColor='rgba(0,0,0,0)';ctx.filter='none';
    const opacity=ramp(t,0,.55)*(1-ramp(t,18.8,20));ctx.globalAlpha=opacity;if(opacity>0)scene(ctx,t);ctx.restore();
  }
  function drawFrame(canvasOrCtx,seconds){const ctx=canvasOrCtx.getContext?canvasOrCtx.getContext('2d'):canvasOrCtx;render(ctx,seconds);return canvasOrCtx;}
  function start(canvas,options={}){
    let running=true,raf=0,origin=performance.now(),offset=Number(options.time)||0;
    const tick=now=>{if(!running)return;const elapsed=offset+(now-origin)/1000;
      drawFrame(canvas,options.loop===false?Math.min(elapsed,META.duration):elapsed%META.duration);
      if(options.loop===false&&elapsed>=META.duration){running=false;return;}raf=requestAnimationFrame(tick);};
    raf=requestAnimationFrame(tick);return {stop(){running=false;cancelAnimationFrame(raf);},seek(t){offset=clamp(t,0,META.duration);origin=performance.now();drawFrame(canvas,offset);}};
  }
  const api=Object.freeze({meta:Object.freeze(META),render,drawFrame,start});
  if(typeof module!=='undefined'&&module.exports)module.exports=api;
  if(root){root.AirportAnimations=root.AirportAnimations||{};root.AirportAnimations[META.id]=api;root.AirportAnimation=api;}
})(typeof globalThis!=='undefined'?globalThis:this);
